// Generates FAKE configmap.yaml + values-testing.yaml in the same shape as the real Helm files
// (no real hosts, certificates or keys). Usage: node tests/fixtures/make-fixtures.mjs tests/fixtures
import fs from 'fs';
const out = process.argv[2];
let n = 0;
const id = () => { n++; const h = n.toString(16).padStart(12, '0'); return `aaaaaaaa-bbbb-4ccc-8ddd-${h}`; };
const N = 8;
const ca = Array.from({ length: 4 }, (_, i) => ({ id: id(), name: `ca-${i}` }));
const cl = Array.from({ length: 2 }, (_, i) => ({ id: id(), name: `client-${i}` }));
const svcs = Array.from({ length: N }, (_, i) => ({ id: id(), name: `svc-${i}`, var: `svc${i}host` }));
const rts = svcs.map((s, i) => ({ id: id(), name: `route-${i}`, svc: s.id }));
// cert wiring: svc-0 & svc-1 share ca-0, svc-1 also ca-1 (only its own), svc-2 has client-0, ca-3 unused, client-1 unused
const caFor = { 0: [ca[0].id], 1: [ca[0].id, ca[1].id], 3: [ca[2].id] };
const clientFor = { 2: cl[0].id };
const L = [];
L.push('# FAKE test configmap — generated by tests/fixtures/make-fixtures.mjs');
L.push('apiVersion: v1', 'kind: ConfigMap', 'metadata:', '  name: kong-declarative', 'data:', '  kong.yml: |', '    _format_version: "2.1"', '    _transform: true', '    services:');
svcs.forEach((s, i) => {
  L.push(`    # ${s.name} backend`);
  L.push(`    - host: {{ .Values.kong_services.${s.var} }}`, '      port: 443', '      retries: 5', '      protocol: https');
  if (clientFor[i]) L.push(`      client_certificate: ${clientFor[i]}`, '      tls_verify: true', '      tls_verify_depth: 2');
  if (caFor[i]) { L.push('      ca_certificates:'); caFor[i].forEach((c) => L.push(`      - ${c}`)); }
  L.push(`      id: ${s.id}`, `      path: /api/v${i}`, '      read_timeout: 6000', '      write_timeout: 6000', '      connect_timeout: 600', `      name: ${s.name}`);
  if (i < N - 1) L.push('');
});
L.push('    routes:');
rts.forEach((r, i) => {
  L.push(`    # ${r.name}`);
  L.push('    - protocols:', '      - http', '      - https', `      service: ${r.svc}`, '      preserve_host: false', '      methods:', '      - GET', '      - POST',
    '      https_redirect_status_code: 426', '      regex_priority: 100', '      strip_path: true', '      path_handling: v0', '      request_buffering: true', '      response_buffering: true',
    `      name: ${r.name}`, `      id: ${r.id}`, '      paths:', `      - /gw/r${i}`);
  if (i < N - 1) L.push('');
});
L.push('    plugins:');
const plugins = [];
svcs.forEach((s, i) => { plugins.push({ id: id(), name: 'rate-limiting', scope: `service: ${s.id}`, cfg: ['minute: 100', 'policy: local'] }); });
plugins.push({ id: id(), name: 'request-transformer', scope: `route: ${rts[0].id}`, cfg: ['add:', '  headers:', '  - "x-gw: kong"'] });
plugins.push({ id: id(), name: 'correlation-id', scope: null, cfg: ['header_name: X-Correlation-ID', 'generator: uuid'], comment: 'global plugin' });
plugins.forEach((p, i) => {
  L.push(`    # ${p.comment || p.name + ' plugin'}`);
  L.push(`    - name: ${p.name}`, `      id: ${p.id}`);
  if (p.scope) L.push(`      ${p.scope}`);
  L.push('      config:'); p.cfg.forEach((c) => L.push(`        ${c}`));
  if (i < plugins.length - 1) L.push('');
});
L.push('    ca_certificates:', '    {{- toYaml .Values.kong_ca_certificates | nindent 4}}');
L.push('    certificates:', '    {{- toYaml .Values.kong_client_certificates | nindent 4}}', '');
fs.writeFileSync(`${out}/configmap.yaml`, L.join('\n'));

const fakePem = (label, ind) => [`${ind}-----BEGIN ${label}-----`, `${ind}RkFLRS1URVNULURBVEEtTk9ULUEtUkVBTC0${label.length}`, `${ind}-----END ${label}-----`];
const V = ['# FAKE test values — no real certificates or keys', 'replicaCount: 1', '', 'kong_ca_certificates:'];
ca.forEach((c) => { V.push(`# ${c.name}`, `- id: ${c.id}`, '  cert: |', ...fakePem('CERTIFICATE', '    ')); });
V.push('', 'kong_client_certificates:');
cl.forEach((c) => { V.push(`# ${c.name}`, '- cert: |-', ...fakePem('CERTIFICATE', '    '), `  id: ${c.id}`, '  key: |-', ...fakePem('PRIVATE KEY', '    ')); });
V.push('', 'kong_services:');
svcs.forEach((s, i) => V.push(`  ${s.var}: 10.10.0.${i + 1}`));
V.push('  unusedvar: example.internal', '');
fs.writeFileSync(`${out}/values-testing.yaml`, V.join('\n'));
console.log({ services: N, routes: N, plugins: plugins.length, ca: ca.length, client: cl.length, vars: N + 1, sharedCa: ca[0].id, onlySvc1Ca: ca[1].id });
